<script>(function () { var rows = Array.prototype.slice.call(document.querySelectorAll('.cycle-row')); var search = document.getElementById('cycle-filter-search'); var status = document.getElementById('cycle-filter-status'); var year = document.getElementById('cycle-filter-year'); var clear = document.getElementById('cycle-filter-clear'); var empty = document.getElementById('cycle-filter-empty'); var params = new URLSearchParams(window.location.search); var debounceTimer; function lower(value) { return value.toLocaleLowerCase(); } function updateUrl() { var next = new URL(window.location.href); [['search', search.value.trim()], ['status', status.value], ['year', year.value]].forEach(function (entry) { if (entry[1]) next.searchParams.set(entry[0], entry[1]); else next.searchParams.delete(entry[0]); }); window.history.replaceState(null, '', next.pathname + (next.search ? next.search : '') + (next.hash ? next.hash : '')); } function highlight(element, query) { var original = element.dataset.originalText || element.textContent; element.dataset.originalText = original; element.textContent = ''; if (!query) { element.textContent = original; return; } var source = lower(original); var needle = lower(query); var cursor = 0; var index; while ((index = source.indexOf(needle, cursor)) !== -1) { element.appendChild(document.createTextNode(original.slice(cursor, index))); var mark = document.createElement('mark'); mark.className = 'tw-rounded tw-bg-amber-100 tw-px-0.5 tw-text-slate-950'; mark.textContent = original.slice(index, index + query.length); element.appendChild(mark); cursor = index + query.length; } element.appendChild(document.createTextNode(original.slice(cursor))); } function renderHighlights(query) { rows.forEach(function (row) { var cells = row.querySelectorAll('td:first-child > div'); Array.prototype.forEach.call(cells, function (cell) { highlight(cell, query); }); }); } function filter(writeUrl) { var rawQuery = search.value.trim(); var query = lower(rawQuery); var visible = rows.filter(function (row) { var match = (!query || row.dataset.search.indexOf(query) !== -1) && (!status.value || row.dataset.status === status.value) && (!year.value || row.dataset.year === year.value); row.classList.toggle('tw-hidden', !match); return match; }); renderHighlights(rawQuery); if (clear) clear.classList.toggle('tw-hidden', rawQuery === ''); if (empty) { empty.classList.toggle('tw-hidden', visible.length !== 0); if (!visible.length) empty.textContent = rawQuery ? 'Tidak ada siklus yang cocok. Coba kata kunci lain atau hapus pencarian.' : 'Tidak ada siklus pada filter ini. Coba ubah status atau tahun akademik.'; } if (writeUrl) updateUrl(); } if (search) search.value = params.get('search') || ''; if (status && params.get('status')) status.value = params.get('status'); if (year && params.get('year')) year.value = params.get('year'); filter(false); if (search) search.addEventListener('input', function () { window.clearTimeout(debounceTimer); debounceTimer = window.setTimeout(function () { filter(true); }, 300); }); if (clear) clear.addEventListener('click', function () { search.value = ''; filter(true); search.focus(); }); [status, year].forEach(function (field) { if (field) field.addEventListener('change', function () { filter(true); }); }); }());</script>
